{
  "name": "super-cloud-hop-3d",
  "private": true,
  "version": "1.0.0",
  "description": "A tiny 3D Mario-style platformer set on floating cloud islands.",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.169.0"
  },
  "devDependencies": {
    "vite": "^5.4.10"
  }
}

:root {
  --sky: #62c8ff;
  --sky-deep: #2e91e6;
  --ink: #10274a;
  --ink-soft: #24446f;
  --cream: #fff9e8;
  --gold: #ffc837;
  --gold-deep: #e28a11;
  --red: #ff4d57;
  --red-deep: #c62838;
  --green: #5ed36b;
  --panel: rgba(16, 39, 74, 0.82);
  --font: "Trebuchet MS", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --font-heavy: "Arial Black", "Trebuchet MS", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: #62c8ff;
  font-family: var(--font);
  color: var(--cream);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

#app { position: fixed; inset: 0; overflow: hidden; }

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

.is-hidden { display: none !important; }

.vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background:
    radial-gradient(ellipse at center, transparent 52%, rgba(10, 27, 54, 0.22) 100%),
    linear-gradient(180deg, rgba(7, 30, 60, 0.12), transparent 18%, transparent 82%, rgba(7, 30, 60, 0.16));
}

/* ---------------------------------- HUD --------------------------------- */

.hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hud__row {
  width: 100%;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.hud__left, .hud__right, .hud__center { display: flex; align-items: center; gap: 12px; }
.hud__left { flex: 1; }
.hud__center { flex-direction: column; gap: 2px; }
.hud__right { flex: 1; justify-content: flex-end; }

.hearts { display: flex; gap: 5px; filter: drop-shadow(0 3px 0 rgba(88, 14, 30, 0.45)); }
.heart {
  width: 30px;
  height: 28px;
  fill: var(--red);
  stroke: #fff6e2;
  stroke-width: 2;
  transition: transform 160ms ease, opacity 200ms ease;
}
.heart.is-empty { fill: rgba(12, 33, 63, 0.36); stroke: rgba(255, 249, 232, 0.4); transform: scale(0.84); }
.heart.is-hit { animation: heart-pop 420ms ease; }

@keyframes heart-pop {
  0% { transform: scale(1); }
  35% { transform: scale(1.35) rotate(-8deg); }
  100% { transform: scale(0.84); }
}

.star-counter {
  display: flex;
  align-items: center;
  gap: 5px;
  font-weight: 900;
  font-size: 20px;
  color: #ffe873;
  text-shadow: 0 3px 0 rgba(120, 62, 6, 0.6);
  padding: 2px 10px 2px 4px;
  border-radius: 999px;
  background: rgba(16, 39, 74, 0.32);
  border: 2px solid rgba(255, 255, 255, 0.22);
}
.star-counter svg { width: 22px; height: 22px; fill: #ffe873; stroke: #9c5b08; stroke-width: 1.5; }

.coin-counter {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heavy);
  font-size: 28px;
  color: #fffdf2;
  letter-spacing: 0.5px;
  text-shadow: 0 3px 0 #a96008, 0 5px 12px rgba(74, 38, 0, 0.35);
  padding: 4px 16px 4px 7px;
  border-radius: 999px;
  background: rgba(16, 39, 74, 0.34);
  border: 2px solid rgba(255, 251, 228, 0.34);
  transition: transform 120ms ease;
}
.coin-counter.is-pop { animation: coin-pop 260ms ease; }
@keyframes coin-pop {
  0% { transform: scale(1); }
  45% { transform: scale(1.12); }
  100% { transform: scale(1); }
}
.coin-counter__total { font-size: 16px; opacity: 0.8; margin-left: -3px; text-shadow: 0 2px 0 #a96008; }
.coin-icon {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 32% 28%, #fff6a4 0%, #ffd646 34%, #f5a412 72%, #c97900 100%);
  border: 3px solid #8f5500;
  box-shadow: inset 0 0 0 3px rgba(255, 247, 180, 0.5), 0 2px 0 rgba(70, 35, 0, 0.35);
  font-size: 16px;
  color: #a75f00;
  font-family: var(--font-heavy);
  line-height: 1;
  padding-bottom: 2px;
  animation: coin-idle 2.6s ease-in-out infinite;
}
@keyframes coin-idle {
  0%, 100% { transform: rotateY(0deg); }
  50% { transform: rotateY(28deg); }
}

.course-label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 3.2px;
  color: rgba(255, 255, 255, 0.82);
  text-shadow: 0 2px 4px rgba(18, 48, 82, 0.6);
}

.hud__right { align-items: center; }

.timer {
  font-family: var(--font-heavy);
  font-size: 22px;
  min-width: 96px;
  text-align: right;
  color: #fffdf2;
  text-shadow: 0 3px 0 rgba(15, 42, 77, 0.55);
  font-variant-numeric: tabular-nums;
}

.icon-btn {
  pointer-events: auto;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  border: 2px solid rgba(255, 255, 255, 0.38);
  background: rgba(16, 39, 74, 0.42);
  color: #fffdf2;
  display: grid;
  place-items: center;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: transform 120ms ease, background 120ms ease;
}
.icon-btn:hover { transform: translateY(-2px); background: rgba(28, 61, 108, 0.65); }
.icon-btn:active { transform: scale(0.94); }
.icon-btn svg { width: 20px; height: 20px; fill: currentColor; }
.icon-btn .icon-off { display: none; }
.icon-btn.is-muted .icon-on { display: none; }
.icon-btn.is-muted .icon-off { display: block; }

/* Boss health */
.boss-bar {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  animation: boss-in 420ms cubic-bezier(0.2, 1.4, 0.4, 1);
}
@keyframes boss-in { from { transform: translateY(-14px) scale(0.9); opacity: 0; } }
.boss-bar__label {
  font-family: var(--font-heavy);
  font-size: 12px;
  letter-spacing: 3px;
  color: #ffe0d0;
  text-shadow: 0 2px 0 #6f101a;
}
.boss-bar__track {
  width: min(360px, 62vw);
  height: 14px;
  border-radius: 999px;
  border: 2px solid rgba(255, 244, 220, 0.7);
  background: rgba(18, 18, 42, 0.55);
  padding: 2px;
  box-shadow: 0 3px 10px rgba(60, 6, 15, 0.3);
}
.boss-bar__fill {
  height: 100%;
  width: 100%;
  border-radius: 999px;
  background: linear-gradient(180deg, #ff8a70, #e8293f 65%, #a8102c);
  transition: width 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.4);
}

/* Toasts */
.toast {
  position: absolute;
  top: 23%;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-heavy);
  font-size: clamp(18px, 3vw, 30px);
  letter-spacing: 2px;
  color: #fffdf2;
  text-shadow: 0 4px 0 #1b5b9d, 0 7px 18px rgba(8, 35, 65, 0.5);
  background: linear-gradient(180deg, rgba(47, 132, 207, 0.92), rgba(22, 80, 145, 0.94));
  border: 3px solid rgba(255, 249, 224, 0.9);
  border-radius: 16px;
  padding: 10px 28px;
  box-shadow: 0 8px 0 rgba(9, 46, 84, 0.4), 0 14px 30px rgba(9, 46, 84, 0.35);
  animation: toast-in 320ms cubic-bezier(0.2, 1.5, 0.4, 1);
  white-space: nowrap;
}
.toast.is-gold {
  color: #5a2b00;
  text-shadow: 0 2px 0 rgba(255, 244, 165, 0.8);
  background: linear-gradient(180deg, #ffe974, #ffb521);
  border-color: #fffbe2;
  box-shadow: 0 8px 0 rgba(152, 83, 0, 0.4), 0 14px 30px rgba(88, 45, 0, 0.3);
}
.toast.is-out { animation: toast-out 300ms ease forwards; }
@keyframes toast-in { from { opacity: 0; transform: translate(-50%, -14px) scale(0.85); } }
@keyframes toast-out { to { opacity: 0; transform: translate(-50%, -18px) scale(0.92); } }

.hint {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 18px;
  align-items: center;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.1px;
  color: rgba(255, 255, 255, 0.88);
  text-shadow: 0 2px 4px rgba(12, 40, 72, 0.55);
  background: rgba(16, 39, 74, 0.3);
  padding: 8px 18px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(6px);
  transition: opacity 600ms ease;
}
.hint.is-faded { opacity: 0; }
.hint span { display: flex; align-items: center; gap: 6px; }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 5px;
  border-radius: 6px;
  background: rgba(255, 252, 240, 0.92);
  color: #1b3d67;
  font-family: var(--font);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.5px;
  box-shadow: 0 2px 0 rgba(9, 36, 66, 0.45);
}
kbd.wide { min-width: 46px; }

/* -------------------------------- Screens ------------------------------- */

.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.title-screen {
  background:
    radial-gradient(ellipse at 50% 42%, rgba(255, 255, 255, 0.08) 0%, rgba(20, 83, 150, 0.28) 52%, rgba(9, 39, 78, 0.62) 100%),
    linear-gradient(180deg, rgba(63, 177, 245, 0.18), rgba(20, 91, 160, 0.25));
  overflow: hidden;
}

.title-card {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 760px;
  animation: card-in 700ms cubic-bezier(0.2, 1, 0.3, 1) both;
}
@keyframes card-in {
  from { opacity: 0; transform: translateY(24px) scale(0.96); }
}
.title-card__eyebrow {
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 6px;
  color: #eaf8ff;
  text-shadow: 0 2px 6px rgba(24, 74, 127, 0.7);
  margin-bottom: 12px;
}
.logo {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 0.82;
  transform: rotate(-1.5deg);
  filter: drop-shadow(0 12px 0 rgba(11, 55, 102, 0.28)) drop-shadow(0 22px 26px rgba(8, 42, 80, 0.46));
}
.logo__super {
  font-family: var(--font-heavy);
  font-size: clamp(24px, 4.2vw, 44px);
  letter-spacing: 12px;
  color: #ffe76b;
  -webkit-text-stroke: 3px #173f72;
  paint-order: stroke fill;
  text-shadow: 0 5px 0 #d08a00;
  transform: rotate(-2deg);
  margin-bottom: 6px;
}
.logo__main {
  font-family: var(--font-heavy);
  font-size: clamp(52px, 10.2vw, 108px);
  letter-spacing: -1px;
  color: #fffdf5;
  -webkit-text-stroke: 7px #173f72;
  paint-order: stroke fill;
  text-shadow:
    0 5px 0 #173f72,
    0 10px 0 #0d2f59,
    0 18px 24px rgba(6, 31, 66, 0.5);
  white-space: nowrap;
}
.logo__main em {
  font-style: normal;
  color: #ffe86b;
  -webkit-text-stroke: 7px #173f72;
}
.logo__three {
  position: absolute;
  right: -8px;
  bottom: -20px;
  font-family: var(--font-heavy);
  font-size: clamp(24px, 4vw, 42px);
  color: #fff;
  background: linear-gradient(180deg, #ff6a5a, #d81f3e);
  border: 4px solid #fff8e6;
  border-radius: 12px;
  padding: 2px 14px 4px;
  transform: rotate(9deg);
  box-shadow: 0 6px 0 rgba(94, 12, 28, 0.45), 0 10px 18px rgba(74, 7, 20, 0.35);
  text-shadow: 0 2px 0 rgba(120, 8, 24, 0.6);
}

.title-card__tag {
  margin: 34px auto 22px;
  font-size: clamp(13px, 1.7vw, 17px);
  font-weight: 700;
  letter-spacing: 0.4px;
  color: #f4fbff;
  text-shadow: 0 2px 6px rgba(9, 41, 76, 0.7);
}

.btn {
  position: relative;
  pointer-events: auto;
  border: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-heavy);
  font-size: 18px;
  letter-spacing: 1.6px;
  color: #fffdf4;
  padding: 16px 34px;
  border-radius: 18px;
  background: linear-gradient(180deg, #ff9a5a 0%, #f1642d 46%, #d44216 100%);
  border: 3px solid #fff7df;
  box-shadow:
    0 7px 0 #9c2c0b,
    0 16px 28px rgba(64, 16, 2, 0.34),
    inset 0 3px 0 rgba(255, 255, 255, 0.45);
  text-shadow: 0 2px 0 rgba(126, 36, 6, 0.6);
  transform: translateY(0);
  transition: transform 120ms ease, box-shadow 120ms ease, filter 120ms ease;
  overflow: hidden;
}
.btn svg { width: 22px; height: 22px; fill: currentColor; }
.btn:hover { transform: translateY(-3px); box-shadow: 0 10px 0 #9c2c0b, 0 20px 32px rgba(64, 16, 2, 0.4), inset 0 3px 0 rgba(255, 255, 255, 0.45); filter: brightness(1.05); }
.btn:active { transform: translateY(4px); box-shadow: 0 3px 0 #9c2c0b, 0 8px 16px rgba(64, 16, 2, 0.35), inset 0 3px 0 rgba(255, 255, 255, 0.4); }
.btn--play { font-size: clamp(18px, 2.2vw, 24px); padding: 18px 46px; margin-bottom: 30px; }
.btn__shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 30%, rgba(255, 255, 255, 0.55) 46%, transparent 62%);
  transform: translateX(-130%);
  animation: shine 3.4s ease-in-out 1.2s infinite;
}
@keyframes shine { 0%, 55% { transform: translateX(-130%); } 75%, 100% { transform: translateX(130%); } }
.btn--ghost {
  background: rgba(17, 46, 84, 0.55);
  box-shadow: 0 6px 0 rgba(8, 30, 58, 0.55), inset 0 2px 0 rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 249, 230, 0.55);
  font-size: 14px;
  padding: 13px 24px;
  text-shadow: none;
}

.title-controls {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px 22px;
  padding: 14px 22px;
  border-radius: 14px;
  background: rgba(12, 43, 79, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(8px);
  max-width: 680px;
  margin: 0 auto;
}
.control { display: flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 700; color: rgba(255, 255, 255, 0.9); letter-spacing: 0.6px; }
.control span { margin-left: 5px; opacity: 0.82; }
.control kbd { background: #fffdf2; }

.title-card__foot {
  margin: 20px 0 0;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.2px;
  color: rgba(234, 248, 255, 0.72);
  text-shadow: 0 2px 5px rgba(10, 40, 74, 0.6);
}

.build-stamp {
  position: absolute;
  bottom: 18px;
  right: 22px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 2.4px;
  color: rgba(255, 255, 255, 0.5);
}

.title-screen__clouds { position: absolute; inset: 0; pointer-events: none; opacity: 0.55; }
.cloud {
  position: absolute;
  width: 220px;
  height: 62px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.85);
  filter: blur(2px);
  box-shadow: 0 18px 40px rgba(26, 97, 162, 0.25);
  animation: drift 26s linear infinite;
}
.cloud::before, .cloud::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  background: inherit;
}
.cloud::before { width: 110px; height: 110px; left: 34px; top: -54px; }
.cloud::after { width: 78px; height: 78px; right: 30px; top: -36px; }
.cloud--1 { top: 12%; left: -10%; animation-duration: 30s; }
.cloud--2 { top: 26%; right: -12%; transform: scale(0.7); animation-duration: 38s; animation-direction: reverse; opacity: 0.8; }
.cloud--3 { bottom: 16%; left: 4%; transform: scale(0.55); animation-duration: 44s; opacity: 0.7; }
.cloud--4 { bottom: 28%; right: 5%; transform: scale(0.4); animation-duration: 34s; animation-direction: reverse; opacity: 0.6; }
@keyframes drift {
  0% { translate: 0 0; }
  50% { translate: 60px -12px; }
  100% { translate: 0 0; }
}

/* Panels */
.pause-screen, .win-screen, .lose-screen { background: rgba(7, 27, 52, 0.6); backdrop-filter: blur(10px); }
.panel {
  width: min(540px, 94vw);
  text-align: center;
  padding: 38px 36px 32px;
  border-radius: 26px;
  background: linear-gradient(180deg, rgba(29, 75, 127, 0.96), rgba(14, 42, 79, 0.98));
  border: 3px solid rgba(255, 249, 229, 0.85);
  box-shadow: 0 12px 0 rgba(5, 22, 42, 0.6), 0 30px 60px rgba(3, 16, 34, 0.55), inset 0 2px 0 rgba(255, 255, 255, 0.25);
  animation: panel-in 380ms cubic-bezier(0.2, 1.3, 0.4, 1) both;
}
@keyframes panel-in { from { opacity: 0; transform: translateY(20px) scale(0.94); } }
.panel__eyebrow { font-size: 11px; font-weight: 900; letter-spacing: 5px; color: #8ed9ff; margin-bottom: 6px; }
.panel h2 { margin: 0 0 12px; font-family: var(--font-heavy); font-size: clamp(36px, 6vw, 56px); letter-spacing: -1px; color: #fffdf4; text-shadow: 0 4px 0 #0a2b52, 0 8px 16px rgba(0, 0, 0, 0.35); }
.panel__text { margin: 0 0 24px; color: rgba(234, 247, 255, 0.76); font-size: 14px; font-weight: 600; }
.panel__actions { display: flex; flex-direction: column; gap: 12px; align-items: center; margin-top: 24px; }
.panel__hint { margin: 20px 0 0; font-size: 11px; color: rgba(220, 240, 255, 0.55); font-weight: 600; }
.panel__hint kbd { height: 20px; font-size: 9px; }

.results { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 8px; }
.result {
  background: rgba(7, 28, 55, 0.48);
  border: 1px solid rgba(140, 208, 255, 0.18);
  border-radius: 14px;
  padding: 12px 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.result span { font-size: 10px; font-weight: 800; letter-spacing: 1.4px; color: rgba(201, 231, 255, 0.62); text-transform: uppercase; }
.result strong { font-family: var(--font-heavy); font-size: 22px; color: #fff6cd; text-shadow: 0 2px 0 rgba(0, 0, 0, 0.3); }

.result-stars { display: flex; justify-content: center; gap: 8px; height: 62px; margin: 4px 0 10px; }
.result-star {
  width: 54px; height: 54px;
  fill: rgba(255, 255, 255, 0.14);
  stroke: rgba(255, 244, 195, 0.35);
  stroke-width: 1.3;
  transform: scale(0.7) rotate(-16deg);
  transition: all 500ms cubic-bezier(0.2, 1.6, 0.4, 1);
}
.result-star.is-earned {
  fill: #ffe873;
  stroke: #9c5b08;
  filter: drop-shadow(0 4px 0 rgba(110, 60, 0, 0.35)) drop-shadow(0 0 16px rgba(255, 221, 94, 0.65));
  transform: scale(1) rotate(0deg);
}
.result-star.is-earned:nth-child(2) { transition-delay: 160ms; }
.result-star.is-earned:nth-child(3) { transition-delay: 320ms; }

.rank-line { margin: 14px 0 0; font-size: 12px; font-weight: 900; letter-spacing: 3px; color: rgba(201, 231, 255, 0.7); }
.rank-line strong { font-family: var(--font-heavy); font-size: 34px; letter-spacing: 0; color: #ffe873; vertical-align: -4px; margin-left: 8px; text-shadow: 0 3px 0 #7b4a03, 0 0 20px rgba(255, 219, 82, 0.5); }
.panel--win h2 { color: #ffe873; }
.panel--lose h2 { color: #ff9d8f; }

/* ------------------------------ Touch UI -------------------------------- */

.touch-controls {
  position: fixed;
  inset: auto 0 0 0;
  z-index: 20;
  padding: 0 26px calc(24px + env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  pointer-events: none;
}
.joystick {
  pointer-events: auto;
  width: 124px;
  height: 124px;
  position: relative;
  border-radius: 50%;
  background: rgba(16, 39, 74, 0.22);
  border: 2px solid rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(4px);
  touch-action: none;
}
.joystick__base {
  position: absolute;
  inset: 18px;
  border-radius: 50%;
  border: 2px dashed rgba(255, 255, 255, 0.2);
}
.joystick__stick {
  position: absolute;
  width: 54px; height: 54px;
  left: 33px; top: 33px;
  border-radius: 50%;
  background: radial-gradient(circle at 36% 30%, #ffffff, #d4e9f8 60%, #9fc5e5);
  border: 2px solid rgba(18, 54, 90, 0.35);
  box-shadow: 0 4px 10px rgba(9, 35, 65, 0.35);
}
.jump-btn {
  pointer-events: auto;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  border: 3px solid #fff8e1;
  font-family: var(--font-heavy);
  font-size: 16px;
  letter-spacing: 1px;
  color: #fff;
  background: radial-gradient(circle at 36% 28%, #ff9a70, #f25a3c 62%, #c82d1d);
  box-shadow: 0 6px 0 #8f1f12, 0 12px 20px rgba(55, 8, 3, 0.4);
  touch-action: none;
  text-shadow: 0 2px 0 rgba(120, 20, 8, 0.55);
}
.jump-btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #8f1f12; }

@media (hover: none) and (pointer: coarse) {
  .hint { display: none; }
  .touch-controls:not(.is-hidden) { display: flex; }
  .hud { padding: 14px 16px; }
  .heart { width: 25px; height: 23px; }
  .coin-counter { font-size: 22px; }
  .coin-icon { width: 25px; height: 25px; font-size: 13px; }
  .timer { font-size: 18px; min-width: 76px; }
  .icon-btn { width: 38px; height: 38px; }
}

@media (max-width: 700px) {
  .hud__row { gap: 8px; }
  .course-label { display: none; }
  .hud__left, .hud__right { gap: 6px; }
  .star-counter { font-size: 16px; padding-right: 7px; }
  .star-counter svg { width: 17px; height: 17px; }
  .coin-counter__total { font-size: 13px; }
  .title-card__tag { margin: 26px auto 16px; }
  .title-controls { gap: 8px 14px; padding: 12px 14px; }
  .control { font-size: 10px; }
  .logo__main { -webkit-text-stroke-width: 5px; text-shadow: 0 4px 0 #173f72, 0 8px 0 #0d2f59, 0 14px 18px rgba(6, 31, 66, 0.5); }
  .logo__main em { -webkit-text-stroke-width: 5px; }
  .logo__three { right: 0; bottom: -14px; border-width: 3px; }
  .screen { padding: 16px; }
  .panel { padding: 30px 22px 26px; }
  .results { gap: 6px; }
  .result strong { font-size: 18px; }
  .rank-line strong { font-size: 28px; }
  .build-stamp { display: none; }
}

@media (max-height: 560px) {
  .title-card__tag { display: none; }
  .title-controls { display: none; }
  .title-card__foot { display: none; }
  .logo { transform: rotate(-1.5deg) scale(0.82); }
  .btn--play { margin-bottom: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}

// Tiny WebAudio sound engine: chiptune-ish SFX plus a gentle looping melody.
// All sound is generated at runtime, so the game needs no external assets.

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sfxBus = null;
    this.musicBus = null;
    this.muted = false;
    this.musicTimer = null;
    this.nextNoteTime = 0;
    this.step = 0;
    this.noiseBuffer = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    this.ctx = new AudioCtx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.7;
    this.master.connect(this.ctx.destination);

    this.sfxBus = this.ctx.createGain();
    this.sfxBus.gain.value = 0.55;
    this.sfxBus.connect(this.master);

    this.musicBus = this.ctx.createGain();
    this.musicBus.gain.value = 0.17;
    this.musicBus.connect(this.master);

    this.noiseBuffer = this.makeNoise(0.5);
    this.startMusic();
  }

  makeNoise(seconds) {
    const rate = this.ctx.sampleRate;
    const buffer = this.ctx.createBuffer(1, rate * seconds, rate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(muted ? 0 : 0.7, now, 0.04);
  }

  tone({ freq = 440, endFreq = freq, type = 'square', duration = 0.12, volume = 0.2, delay = 0, attack = 0.005, bus = null }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(volume, t + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(gain);
    gain.connect(bus || this.sfxBus);
    osc.start(t);
    osc.stop(t + duration + 0.02);
  }

  noise({ duration = 0.15, volume = 0.18, delay = 0, filterFreq = 900, q = 1, bus = null }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(filterFreq, t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, filterFreq * 0.4), t + duration);
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(volume, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(bus || this.sfxBus);
    src.start(t);
    src.stop(t + duration + 0.02);
  }

  jump() {
    this.tone({ freq: 300, endFreq: 720, type: 'square', duration: 0.16, volume: 0.16 });
    this.tone({ freq: 600, endFreq: 1100, type: 'triangle', duration: 0.1, volume: 0.08, delay: 0.02 });
  }

  doubleJump() {
    this.tone({ freq: 520, endFreq: 1080, type: 'triangle', duration: 0.18, volume: 0.14 });
  }

  land() {
    this.noise({ duration: 0.09, volume: 0.1, filterFreq: 700, q: 0.8 });
  }

  coin() {
    this.tone({ freq: 1046.5, type: 'square', duration: 0.07, volume: 0.12 });
    this.tone({ freq: 1568, type: 'square', duration: 0.16, volume: 0.12, delay: 0.06 });
  }

  star() {
    const notes = [784, 988, 1175, 1568, 1976];
    notes.forEach((f, i) => this.tone({ freq: f, type: 'triangle', duration: 0.18, volume: 0.16, delay: i * 0.07 }));
  }

  stomp() {
    this.tone({ freq: 260, endFreq: 90, type: 'square', duration: 0.16, volume: 0.22 });
    this.noise({ duration: 0.12, volume: 0.16, filterFreq: 500 });
  }

  hurt() {
    this.tone({ freq: 420, endFreq: 120, type: 'sawtooth', duration: 0.4, volume: 0.2 });
    this.tone({ freq: 300, endFreq: 90, type: 'square', duration: 0.5, volume: 0.12, delay: 0.05 });
  }

  spring() {
    this.tone({ freq: 220, endFreq: 1250, type: 'sine', duration: 0.3, volume: 0.2 });
    this.tone({ freq: 440, endFreq: 1800, type: 'triangle', duration: 0.28, volume: 0.1, delay: 0.03 });
  }

  checkpoint() {
    const notes = [523, 659, 784, 1046];
    notes.forEach((f, i) => this.tone({ freq: f, type: 'triangle', duration: 0.28, volume: 0.14, delay: i * 0.09 }));
  }

  bump() {
    this.tone({ freq: 180, endFreq: 140, type: 'square', duration: 0.08, volume: 0.15 });
  }

  bossHit() {
    this.tone({ freq: 140, endFreq: 70, type: 'sawtooth', duration: 0.28, volume: 0.18 });
    this.noise({ duration: 0.2, volume: 0.16, filterFreq: 400 });
  }

  win() {
    const melody = [523, 659, 784, 1046, 1318, 1046, 1318, 1568];
    melody.forEach((f, i) => this.tone({ freq: f, type: 'triangle', duration: 0.32, volume: 0.16, delay: i * 0.13 }));
    melody.forEach((f, i) => this.tone({ freq: f / 2, type: 'square', duration: 0.26, volume: 0.06, delay: i * 0.13 }));
  }

  gameOver() {
    const melody = [392, 330, 262, 196];
    melody.forEach((f, i) => this.tone({ freq: f, type: 'triangle', duration: 0.4, volume: 0.16, delay: i * 0.18 }));
  }

  click() {
    this.tone({ freq: 660, endFreq: 880, type: 'triangle', duration: 0.06, volume: 0.12 });
  }

  startMusic() {
    if (!this.ctx || this.musicTimer) return;
    this.nextNoteTime = this.ctx.currentTime + 0.2;
    this.step = 0;
    this.musicTimer = setInterval(() => this.scheduleMusic(), 40);
  }

  scheduleMusic() {
    if (!this.ctx) return;
    const stepDuration = 0.155;
    while (this.nextNoteTime < this.ctx.currentTime + 0.2) {
      this.playStep(this.step, this.nextNoteTime);
      this.step = (this.step + 1) % 64;
      this.nextNoteTime += stepDuration;
    }
  }

  playStep(step, time) {
    if (this.muted) return;
    const bar = Math.floor(step / 16) % 4;
    const beat = step % 16;
    // Lead melody (two 4-bar phrases)
    const lead = [
      659, 0, 784, 0, 880, 784, 659, 0, 587, 0, 659, 0, 523, 0, 0, 0,
      659, 0, 784, 0, 988, 880, 784, 0, 698, 0, 784, 0, 659, 0, 0, 0,
      880, 0, 988, 0, 1046, 988, 880, 0, 784, 0, 880, 0, 698, 0, 0, 0,
      659, 784, 880, 0, 1046, 0, 988, 880, 784, 0, 659, 0, 523, 0, 0, 0,
    ];
    const note = lead[step];
    if (note) this.noteAt(note, time, 'triangle', 0.05, 0.16);
    if (note && step % 4 === 0) this.noteAt(note / 2, time, 'square', 0.024, 0.11);

    // Bass roots per bar: C, A minor, F, G
    const roots = [130.81, 110, 87.31, 98];
    if (beat === 0 || beat === 8) this.noteAt(roots[bar], time, 'triangle', 0.09, 0.2);
    if (beat === 4 || beat === 12) this.noteAt(roots[bar] * 1.5, time, 'triangle', 0.055, 0.16);

    // Soft percussion
    if (beat % 2 === 0) this.hatAt(time, beat % 4 === 0 ? 0.035 : 0.02);
    if (beat === 0 || beat === 8) this.kickAt(time);
  }

  noteAt(freq, time, type, volume, duration) {
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.exponentialRampToValueAtTime(volume, time + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    osc.connect(gain);
    gain.connect(this.musicBus);
    osc.start(time);
    osc.stop(time + duration + 0.02);
  }

  hatAt(time, volume) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 7000;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(volume, time);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.035);
    src.connect(filter); filter.connect(gain); gain.connect(this.musicBus);
    src.start(time); src.stop(time + 0.05);
  }

  kickAt(time) {
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(120, time);
    osc.frequency.exponentialRampToValueAtTime(45, time + 0.1);
    gain.gain.setValueAtTime(0.08, time);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.12);
    osc.connect(gain); gain.connect(this.musicBus);
    osc.start(time); osc.stop(time + 0.14);
  }
}

import * as THREE from 'three';

// Shared cartoon gradient for MeshToonMaterial (three soft steps).
let gradientMap = null;
export function toonGradient() {
  if (gradientMap) return gradientMap;
  const data = new Uint8Array([88, 150, 210, 255]);
  gradientMap = new THREE.DataTexture(data, data.length, 1, THREE.RedFormat);
  gradientMap.minFilter = THREE.NearestFilter;
  gradientMap.magFilter = THREE.NearestFilter;
  gradientMap.generateMipmaps = false;
  gradientMap.needsUpdate = true;
  return gradientMap;
}

export function toon(color, extra = {}) {
  return new THREE.MeshToonMaterial({ color, gradientMap: toonGradient(), ...extra });
}

const OUTLINE_MAT = new THREE.MeshBasicMaterial({ color: 0x12213d, side: THREE.BackSide });
function addOutline(mesh, scale = 1.09) {
  const outline = new THREE.Mesh(mesh.geometry, OUTLINE_MAT);
  outline.scale.setScalar(scale);
  outline.castShadow = false;
  outline.receiveShadow = false;
  mesh.add(outline);
  return mesh;
}

function mesh(geo, mat, { outline = false, shadow = true } = {}) {
  const m = new THREE.Mesh(geo, mat);
  m.castShadow = shadow;
  m.receiveShadow = false;
  if (outline) addOutline(m);
  return m;
}

const matCache = new Map();
function cachedToon(color) {
  if (!matCache.has(color)) matCache.set(color, toon(color));
  return matCache.get(color);
}

// ------------------------------- Hero --------------------------------------

export function createHero() {
  const root = new THREE.Group();
  root.name = 'hero';

  const body = new THREE.Group();
  root.add(body);

  const skin = toon(0xffc58f);
  const skinDark = toon(0xe8a06b);
  const red = toon(0xe8333f);
  const redDark = toon(0xbb1f2e);
  const blue = toon(0x2c62d4);
  const blueDark = toon(0x1e47a3);
  const brown = toon(0x7a401e);
  const white = toon(0xfff8ea);
  const black = toon(0x1b2033);
  const gold = toon(0xffcf3f);

  // Legs (pivot at hip)
  const legs = [];
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group();
    pivot.position.set(side * 0.17, 0.72, 0);
    const leg = mesh(new THREE.CylinderGeometry(0.115, 0.1, 0.5, 8), blueDark, { outline: true });
    leg.position.y = -0.26;
    pivot.add(leg);
    const shoe = mesh(new THREE.BoxGeometry(0.27, 0.18, 0.42), brown, { outline: true });
    shoe.position.set(0, -0.56, 0.08);
    shoe.geometry.translate(0, 0, 0.03);
    pivot.add(shoe);
    body.add(pivot);
    legs.push(pivot);
  }

  // Torso
  const torso = new THREE.Group();
  torso.position.y = 1.02;
  body.add(torso);

  const shirt = mesh(new THREE.BoxGeometry(0.6, 0.46, 0.4), red, { outline: true });
  shirt.position.y = 0.08;
  torso.add(shirt);

  const overalls = mesh(new THREE.BoxGeometry(0.64, 0.34, 0.44), blue, { outline: true });
  overalls.position.y = -0.17;
  torso.add(overalls);

  const bib = mesh(new THREE.BoxGeometry(0.34, 0.26, 0.06), blue, { outline: true });
  bib.position.set(0, 0.06, 0.22);
  torso.add(bib);

  // Overall buttons
  for (const side of [-1, 1]) {
    const button = mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.03, 10), gold, { shadow: false });
    button.rotation.x = Math.PI / 2;
    button.position.set(side * 0.15, 0.13, 0.255);
    torso.add(button);
  }

  // Arms (pivot at shoulder)
  const arms = [];
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group();
    pivot.position.set(side * 0.36, 1.24, 0);
    const sleeve = mesh(new THREE.CylinderGeometry(0.095, 0.085, 0.3, 8), red, { outline: true });
    sleeve.position.y = -0.14;
    pivot.add(sleeve);
    const glove = mesh(new THREE.SphereGeometry(0.13, 10, 8), white, { outline: true });
    glove.position.y = -0.33;
    pivot.add(glove);
    body.add(pivot);
    arms.push(pivot);
  }

  // Head
  const head = new THREE.Group();
  head.position.y = 1.7;
  body.add(head);

  const skull = mesh(new THREE.SphereGeometry(0.36, 18, 14), skin, { outline: true });
  skull.scale.set(1, 1.02, 0.96);
  head.add(skull);

  // Ears
  for (const side of [-1, 1]) {
    const ear = mesh(new THREE.SphereGeometry(0.1, 10, 8), skin, { shadow: false });
    ear.position.set(side * 0.34, -0.02, 0);
    head.add(ear);
  }

  // Eyes
  for (const side of [-1, 1]) {
    const eye = mesh(new THREE.SphereGeometry(0.09, 10, 8), white, { shadow: false });
    eye.scale.set(0.85, 1.2, 0.55);
    eye.position.set(side * 0.125, 0.07, 0.305);
    head.add(eye);
    const pupil = mesh(new THREE.SphereGeometry(0.045, 8, 8), black, { shadow: false });
    pupil.scale.set(0.9, 1.1, 0.5);
    pupil.position.set(side * 0.125, 0.07, 0.35);
    head.add(pupil);
  }

  // Nose
  const nose = mesh(new THREE.SphereGeometry(0.11, 12, 10), skinDark, { shadow: false });
  nose.scale.set(1.05, 0.9, 0.85);
  nose.position.set(0, -0.05, 0.355);
  head.add(nose);

  // Moustache
  for (const side of [-1, 1]) {
    const stache = mesh(new THREE.SphereGeometry(0.09, 10, 8), brown, { shadow: false });
    stache.scale.set(1.3, 0.55, 0.55);
    stache.position.set(side * 0.1, -0.16, 0.31);
    stache.rotation.z = side * 0.22;
    head.add(stache);
  }

  // Cap dome
  const cap = new THREE.Group();
  cap.position.set(0, 0.19, -0.01);
  head.add(cap);

  const dome = mesh(new THREE.SphereGeometry(0.385, 18, 12, 0, Math.PI * 2, 0, Math.PI / 2), red, { outline: true });
  dome.scale.set(1, 0.9, 1);
  cap.add(dome);

  const brim = mesh(new THREE.CylinderGeometry(0.32, 0.34, 0.07, 18, 1, false, -Math.PI / 2, Math.PI), redDark, { outline: true });
  brim.scale.z = 1.15;
  brim.position.set(0, 0.005, 0.24);
  brim.rotation.x = -0.05;
  cap.add(brim);

  // Cap badge: white disc + red star-ish gem
  const badge = mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.035, 12), white, { shadow: false });
  badge.rotation.x = Math.PI / 2;
  badge.position.set(0, 0.13, 0.33);
  cap.add(badge);
  const gem = mesh(new THREE.OctahedronGeometry(0.055), gold, { shadow: false });
  gem.position.set(0, 0.13, 0.36);
  gem.scale.z = 0.45;
  cap.add(gem);

  // Backpack for silhouette interest
  const pack = mesh(new THREE.BoxGeometry(0.3, 0.28, 0.16), blueDark, { outline: true });
  pack.position.set(0, 1.1, -0.27);
  body.add(pack);

  root.traverse((o) => {
    if (o.isMesh) o.frustumCulled = false;
  });

  return {
    root,
    body,
    torso,
    head,
    cap,
    legs,
    arms,
    materials: { red, redDark, blue, blueDark, skin, skinDark, brown, white, black, gold },
  };
}

// ------------------------------ Goomba -------------------------------------

export function createGoomba({ scale = 1, boss = false } = {}) {
  const root = new THREE.Group();
  root.scale.setScalar(scale);

  const body = new THREE.Group();
  root.add(body);

  const capMat = boss ? toon(0x7b3fd4) : toon(0xd9343b);
  const capDark = boss ? toon(0x55259a) : toon(0x9f1f28);
  const skin = toon(0xf6d7a6);
  const footMat = toon(0x5a3217);
  const white = toon(0xfff8ea);
  const black = toon(0x1a1c2c);

  // Head/cap
  const head = new THREE.Group();
  head.position.y = 0.6;
  body.add(head);

  const cap = mesh(new THREE.SphereGeometry(0.55, 16, 12, 0, Math.PI * 2, 0, Math.PI / 1.9), capMat, { outline: true });
  cap.scale.set(1, 0.8, 1);
  head.add(cap);

  const face = mesh(new THREE.SphereGeometry(0.48, 16, 12), skin, { outline: true });
  face.scale.set(1, 0.68, 0.9);
  face.position.y = -0.13;
  head.add(face);

  // Spots on the cap
  const spotGeo = new THREE.SphereGeometry(0.16, 10, 8);
  const spots = [
    [0, 0.44, 0.1, 1.0],
    [-0.34, 0.3, 0.22, 0.7],
    [0.36, 0.34, -0.02, 0.62],
    [0.08, 0.32, -0.4, 0.8],
  ];
  for (const [x, y, z, s] of spots) {
    const spot = mesh(spotGeo, white, { shadow: false });
    spot.scale.setScalar(s * 0.7);
    spot.position.set(x, y, z);
    if (z > 0.1) spot.position.z += 0.32;
    head.add(spot);
  }

  // Eyes (angry)
  for (const side of [-1, 1]) {
    const eye = mesh(new THREE.SphereGeometry(0.1, 8, 8), white, { shadow: false });
    eye.scale.set(0.8, 1.1, 0.45);
    eye.position.set(side * 0.15, -0.05, 0.42);
    head.add(eye);
    const pupil = mesh(new THREE.SphereGeometry(0.05, 8, 8), black, { shadow: false });
    pupil.position.set(side * 0.14, -0.07, 0.47);
    pupil.scale.z = 0.4;
    head.add(pupil);
    const brow = mesh(new THREE.BoxGeometry(0.18, 0.05, 0.05), capDark, { shadow: false });
    brow.position.set(side * 0.15, 0.07, 0.46);
    brow.rotation.z = side * 0.35;
    head.add(brow);
  }

  // Fangs
  for (const side of [-1, 1]) {
    const fang = mesh(new THREE.ConeGeometry(0.035, 0.1, 5), white, { shadow: false });
    fang.position.set(side * 0.12, -0.26, 0.44);
    fang.rotation.x = Math.PI;
    head.add(fang);
  }

  // Feet
  const feet = [];
  for (const side of [-1, 1]) {
    const foot = mesh(new THREE.SphereGeometry(0.22, 10, 8), footMat, { outline: true });
    foot.scale.set(1, 0.55, 1.25);
    foot.position.set(side * 0.28, 0.12, 0.06);
    body.add(foot);
    feet.push(foot);
  }

  root.traverse((o) => {
    if (o.isMesh) o.frustumCulled = false;
  });

  return { root, body, head, feet, scaleValue: scale };
}

