  display: inline-grid;
  place-items: center;
  min-height: 22px;
  padding: 0 7px;
  border-radius: 6px;
  background: rgba(255, 252, 240, 0.92);
  color: #1b3d67;
  font-size: 10px;
  font-weight: 900;
  box-shadow: 0 2px 0 rgba(9, 36, 66, 0.45);
}
.title-controls--touch .control span:last-child { opacity: 0.75; }

@media (hover: none) and (pointer: coarse) {
  .title-controls--keyboard { display: none; }
  .title-controls--touch { display: flex; }
}

/* Compact HUD for narrow screens */
@media (max-width: 700px) {
  .hud { padding: 12px 12px; }
  .hud__row { gap: 4px; }
  .hud__left, .hud__right { gap: 4px; }
