import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.getByRole('button', { name: 'PLAY GAME' }).click()
await page.waitForTimeout(1000)
const res = await page.evaluate(() => {
  const g = window.__cloudHop.game
  window.__cloudHop.teleport(0, 12.1, -81)
  g.cameraState.yaw = 0; g.cameraState.pitch = 0.35; g.snapCamera()
  for (let i = 0; i < 30; i++) g.update(1 / 60)
  const cam = g.camera.position
  const coins = window.__cloudHop.world.coins.filter(c => !c.collected)
    .map(c => ({ d: cam.distanceTo(c.group.position).toFixed(2), vis: c.group.visible, p: c.group.position.toArray().map(v => +v.toFixed(2)) }))
    .sort((a, b) => a.d - b.d).slice(0, 8)
  return { cam: cam.toArray(), coins }
})
console.log(JSON.stringify(res, null, 2))
await browser.close()

