import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const context = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
})
const page = await context.newPage()
const failures = []
page.on('pageerror', e => failures.push('pageerror: ' + e.message))
page.on('console', m => { if (m.type() === 'error') failures.push('console: ' + m.text()) })
await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.waitForTimeout(500)
await page.screenshot({ path: join(out, 'mobile-title2.png') })
await page.getByRole('button', { name: 'PLAY GAME' }).click()
await page.waitForTimeout(1400)
await page.screenshot({ path: join(out, 'mobile-game2.png') })
const boxes = await page.evaluate(() => {
  const pick = id => {
    const el = document.getElementById(id)
    const r = el.getBoundingClientRect()
    return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), display: getComputedStyle(el).display }
  }
  return {
    hud: pick('hud'),
    joystick: pick('joystick'),
    jump: pick('jump-btn'),
    hint: pick('hint'),
    canvas: pick('game'),
    inner: [innerWidth, innerHeight],
    touchHints: getComputedStyle(document.querySelector('.desktop-hints')).display,
    status: window.__cloudHop.state.status,
  }
})
// Real pointer drag on the joystick to confirm the stick drives movement.
const joy = await page.locator('#joystick').boundingBox()
const before = await page.evaluate(() => window.__cloudHop.state.pos)
await page.mouse.move(joy.x + joy.width / 2, joy.y + joy.height / 2)
await page.mouse.down()
await page.mouse.move(joy.x + joy.width / 2 + 30, joy.y + joy.height / 2 - 30, { steps: 4 })
await page.waitForTimeout(900)
await page.mouse.up()
const after = await page.evaluate(() => window.__cloudHop.state.pos)
// Tap the JUMP button through a real touch event.
await page.locator('#jump-btn').tap()
await page.waitForTimeout(500)
const jumped = await page.evaluate(() => ({ y: window.__cloudHop.state.pos[1], grounded: window.__cloudHop.state.grounded }))
console.log(JSON.stringify({ boxes, before, after, jumped, failures }, null, 2))
await browser.close()

